<?php
require __DIR__.'/config.php';
if(isset($_GET['logout'])){session_destroy();header('Location:index.php');exit;}
if(isset($_POST['login'])){if($_POST['user']===ADMIN_USER && hash_equals('JADIEL-ADMIN-2026',$_POST['pass']??'')){$_SESSION['iptv_admin']=true;header('Location:index.php');exit;}flash('Usuário ou senha inválidos.');}
if(!logged()):?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=APP_NAME?> — Login</title><style><?=css()?></style></head><body class="login"><div class="loginbox"><div class="logo">J<span>•</span>IPTV</div><div class="eyebrow">PAINEL ADMINISTRATIVO</div><h1>Controle sua operação IPTV.</h1><p>Gerencie clientes, planos, listas M3U, servidores e acessos em um único painel.</p><form method="post"><label>Usuário<input name="user" autocomplete="username" required></label><label>Senha<input type="password" name="pass" autocomplete="current-password" required></label><button name="login" class="primary">Entrar no painel →</button></form><?php if($m=get_flash()):?><div class="alert"><?=$m?></div><?php endif;?></div></body></html><?php exit;endif;
$clients=data_read('clients.json');$servers=data_read('servers.json');$plans=data_read('plans.json');$lists=data_read('lists.json');$orders=data_read('orders.json');
$active=count(array_filter($clients,fn($x)=>($x['status']??'')==='active'));$online=array_sum(array_map(fn($x)=>(int)($x['online']??0),$servers));$revenue=array_sum(array_map(fn($x)=>(float)($x['price']??0),$orders));
$section=$_GET['page']??'dashboard';
if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['action'])){
 $a=$_POST['action'];
 if($a==='client'){ $clients[]=['id'=>bin2hex(random_bytes(4)),'name'=>trim($_POST['name']),'username'=>trim($_POST['username']),'password'=>trim($_POST['password']),'plan'=>trim($_POST['plan']),'status'=>'active','expires'=>trim($_POST['expires']),'created'=>date('c')];data_write('clients.json',$clients);flash('Cliente criado com sucesso.');header('Location:index.php?page=clients');exit;}
 if($a==='server'){ $servers[]=['id'=>bin2hex(random_bytes(4)),'name'=>trim($_POST['name']),'url'=>trim($_POST['url']),'status'=>'online','online'=>0];data_write('servers.json',$servers);flash('Servidor adicionado.');header('Location:index.php?page=servers');exit;}
 if($a==='plan'){ $plans[]=['id'=>bin2hex(random_bytes(4)),'name'=>trim($_POST['name']),'price'=>(float)$_POST['price'],'days'=>(int)$_POST['days'],'active'=>true];data_write('plans.json',$plans);flash('Plano criado.');header('Location:index.php?page=plans');exit;}
 if($a==='list'){ $lists[]=['id'=>bin2hex(random_bytes(4)),'name'=>trim($_POST['name']),'url'=>trim($_POST['url']),'category'=>trim($_POST['category'])];data_write('lists.json',$lists);flash('Lista M3U cadastrada.');header('Location:index.php?page=lists');exit;}
}
