,1fr);gap:14px}.card{background:linear-gradient(145deg,#0b1711,#07100c);border:1px solid #ffffff0d;border-radius:18px;padding:18px;box-shadow:0 18px 45px #0004}.metric{font-size:28px;font-weight:950;margin-top:8px}.label{color:#738a7f;font-size:12px}.toolbar{display:flex;justify-content:space-between;align-items:center;gap:10px;margin:25px 0 14px}.btn{border:1px solid #244636;background:#ffffff06;color:#dffbed;padding:10px 14px;border-radius:11px;cursor:pointer}.btn.green{background:#31ed98;color:#03140c;border:0;font-weight:900}.table{overflow:auto;border:1px solid #ffffff0d;border-radius:18px;background:#08110d}.table table{width:100%;border-collapse:collapse;min-width:700px}.table th,.table td{text-align:left;padding:14px;border-bottom:1px solid #ffffff08}.table th{color:#6e887b;font-size:11px;text-transform:uppercase}.status{color:#45f5a0}.formbox{max-width:650px}.form{display:grid;grid-template-columns:1fr 1fr;gap:10px}.form .full{grid-column:1/-1}.form button{grid-column:1/-1}@media(max-width:800px){.side{width:68px;padding:15px 8px}.brand{font-size:0;text-align:center}.brand:after{content:'J';font-size:22px;color:#31ed98}.navtitle{display:none}.nav a{font-size:0;text-align:center}.nav a:before{content:'•';font-size:18px}.content{margin-left:68px;width:calc(100% - 68px);padding:20px 14px}.grid{grid-template-columns:1fr 1fr}.form{grid-template-columns:1fr}}@media(max-width:500px){.grid{grid-template-columns:1fr}.top h1{font-size:22px}}
CSS;}
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=APP_NAME?></title><style><?=css()?></style></head><body><div class="layout"><aside class="side"><div class="brand">JADIEL <b>IPTV</b></div><nav class="nav"><div class="navtitle">PRINCIPAL</div><?php $nav=['dashboard'=>'Dashboard','clients'=>'Clientes','servers'=>'Servidores','plans'=>'Planos','lists'=>'Listas M3U'];foreach($nav as $k=>$v):?><a class="<?=$section===$k?'active':''?>" href="?page=<?=$k?>"><?=$v?></a><?php endforeach;?><div class="navtitle">SISTEMA</div><a href="?logout=1">Sair</a></nav></aside><main class="content"><header class="top"><div><div class="label">PAINEL IPTV</div><h1><?=h(['dashboard'=>'Visão geral','clients'=>'Clientes','servers'=>'Servidores','plans'=>'Planos','lists'=>'Listas M3U'][$section]??'Dashboard')?></h1></div><a class="logout" href="?logout=1">Sair</a></header><?php if($m=get_flash()):?><div class="card" style="margin-bottom:15px;color:#45f5a0"><?=$m?></div><?php endif;?>
