<?php elseif($section==='clients'):?><div class="card formbox"><h2>Novo cliente</h2><form method="post" class="form"><input type="hidden" name="action" value="client"><label>Nome<input name="name" required></label><label>Usuário<input name="username" required></label><label>Senha<input name="password" required></label><label>Plano<input name="plan"></label><label class="full">Validade<input type="date" name="expires"></label><button class="btn green">Criar cliente</button></form></div><div class="toolbar"><h2>Clientes</h2></div><div class="table"><table><tr><th>Nome</th><th>Usuário</th><th>Plano</th><th>Validade</th><th>Status</th></tr><?php foreach($clients as $x):?><tr><td><?=h($x['name'])?></td><td><?=h($x['username'])?></td><td><?=h($x['plan'])?></td><td><?=h($x['expires'])?></td><td class="status"><?=h($x['status'])?></td></tr><?php endforeach;?></table></div>
<?php elseif($section==='servers'):?><div class="card formbox"><h2>Novo servidor</h2><form method="post" class="form"><input type="hidden" name="action" value="server"><label>Nome<input name="name" placeholder="Servidor BR 01" required></label><label>URL/Host<input name="url" required></label><button class="btn green">Adicionar servidor</button></form></div><div class="toolbar"><h2>Servidores</h2></div><div class="table"><table><tr><th>Nome</th><th>URL</th><th>Status</th><th>Online</th></tr><?php foreach($servers as $x):?><tr><td><?=h($x['name'])?></td><td><?=h($x['url'])?></td><td class="status"><?=h($x['status'])?></td><td><?=h($x['online'])?></td></tr><?php endforeach;?></table></div>
<?php elseif($section==='plans'):?><div class="card formbox"><h2>Novo plano</h2><form method="post" class="form"><input type="hidden" name="action" value="plan"><label>Nome<input name="name" placeholder="Plano 30 dias" required></label><label>Preço<input type="number" step="0.01" name="price" required></label><label class="full">Dias<input type="number" name="days" value="30" required></label><button class="btn green">Criar plano</button></form></div><div class="toolbar"><h2>Planos</h2></div><div class="table"><table><tr><th>Plano</th><th>Preço</th><th>Duração</th></tr><?php foreach($plans as $x):?><tr><td><?=h($x['name'])?></td><td>R$ <?=number_format($x['price'],2,',','.')?></td><td><?=h($x['days'])?> dias</td></tr><?php endforeach;?></table></div>
<?php elseif($section==='lists'):?><div class="card formbox"><h2>Adicionar lista M3U</h2><form method="post" class="form"><input type="hidden" name="action" value="list"><label>Nome<input name="name" placeholder="Lista principal" required></label><label>Categoria<input name="category" placeholder="TV"></label><label class="full">URL M3U<input name="url" required></label><button class="btn green">Salvar lista</button></form></div><div class="toolbar"><h2>Listas cadastradas</h2></div><div class="table"><table><tr><th>Nome</th><th>Categoria</th><th>URL</th></tr><?php foreach($lists as $x):?><tr><td><?=h($x['name'])?></td><td><?=h($x['category'])?></td><td><?=h($x['url'])?></td></tr><?php endforeach;?></table></div><?php endif;?></main></div></body></html>